	'start_mail_subject' => 'Demande de journée de découverte',
	'why_h' => 'Un dessin ne peut pas vous dire où viendra reposer un pouce. Un morceau de mousse le peut, en un après-midi.',
	'why_sub' => 'Maquettes en mousse réalisées dans notre propre atelier : 138 pour les quatre projets de cette page.',
	'wk_c_after' => 'Après · le stylo finalisé',
	'wk_c_before' => 'Avant · pièces d\'étude de la molette',
	'wk_c_cap1' => 'Stylo injecteur Tally. Les patients souffrant de raideurs articulaires ne parvenaient ni à lire ni à tourner la molette de dosage.',
	'wk_c_cap2' => 'Une molette élargie à fort contraste et un cliquet souple, validés au terme de 56 études en mousse et résine.',
	'wk_c_facts' => '56 maquettes en mousse · 18 mois jusqu\'au premier échantillon d\'outillage · Juin 2025',
	'wk_d_after' => 'À l\'usine · première pièce sortie d\'outillage',
	'wk_d_before' => 'L\'enceinte finalisée',
	'wk_d_cap1' => 'Enceinte Pell. Le premier prototype coûtait deux fois son budget cible et ne pouvait être assemblé sans colle.',
	'wk_d_cap2' => 'Trois pièces moulées emboîtables avec fixations par encliquetage : aucun adhésif et un coût unitaire réduit de moitié.',
	'wk_d_facts' => '18 maquettes en mousse · 9 mois jusqu\'au premier échantillon d\'outillage · Janv. 2025',
	'wk_desc' => 'Quatre produits, présentés chacun sous forme de maquette en mousse puis de pièce finale.',
	'wk_h0' => 'Combiné Cradle pour les soins hospitaliers au chevet',
	'wk_h1' => 'Bouilloire Mora pour un usage quotidien en cuisine',
	'wk_h2' => 'Stylo injecteur Tally pour des injections reproductibles',
	'wk_h3' => 'Enceinte Pell pour un assemblage mécanique propre',
	'wk_l_a' => 'Cas A',
